parameters.jsCode:
// Convierte la respuesta de Gemini (clasificacion) en 3 campos VALIDOS.
// Si el modelo devuelve algo fuera del catalogo (o un JSON roto) se usa un valor por defecto y se marca clasificacion_fallback.
const ENUMS = {
  sentimiento: ['positivo', 'negativo', 'neutro'],
  intencion: ['reembolso', 'consulta', 'queja', 'otro'],
  prioridad: ['alta', 'media', 'baja'],
};
const DEFAULTS = { sentimiento: 'neutro', intencion: 'otro', prioridad: 'media' };

const r = $input.item.json;
// Gemini generateContent -> candidates[0].content.parts[].text
const texto = (r.candidates?.[0]?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join('');
const modelo = String(r.modelVersion ?? 'gemini-3.6-flash');

// toma el primer bloque {...} del texto (tolera bloques de codigo o texto extra alrededor del JSON)
let crudo = {};
try {
  const m = String(texto).match(/\{[\s\S]*\}/);
  crudo = m ? JSON.parse(m[0]) : {};
} catch (e) {
  crudo = {};
}
if (crudo === null || typeof crudo !== 'object') crudo = {};

const limpiar = (v) => String(v ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const salida = {};
let fallback = false;
for (const clave of Object.keys(ENUMS)) {
  const v = limpiar(crudo[clave]);
  if (ENUMS[clave].includes(v)) {
    salida[clave] = v;
  } else {
    salida[clave] = DEFAULTS[clave];
    fallback = true;
  }
}
salida.clasificacion_fallback = fallback;
salida.modelo_clasificacion = modelo || 'desconocido';
return { json: salida };

// RAG: concatena los articulos verificados de la Base de Conocimiento en un solo texto para el prompt.
const MAX_CHARS = 12000; // tope de contexto (control de costo)
const articulos = $input.all()
  .map((i) => ({
    titulo: String(i.json.property_t_tulo ?? '').trim(),
    contenido: String(i.json.property_contenido ?? '').trim(),
  }))
  .filter((a) => a.titulo || a.contenido)
  .map((a) => a.titulo + ': ' + a.contenido);

let kb = articulos.join('\n---\n');
if (!kb) kb = '(La base de conocimiento no tiene articulos verificados.)';
return [{ json: { kb_texto: kb.slice(0, MAX_CHARS), kb_articulos: articulos.length } }];

// Mapea la respuesta de Gemini (candidates[0].content.parts[].text) a un campo limpio y la valida.
const r = $input.item.json;
const cand = r.candidates?.[0];
const borrador = (cand?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join('').trim();

let motivo = '';
if (!cand) {
  motivo = 'Gemini no devolvio candidatos' + (r.promptFeedback?.blockReason ? ' (bloqueado: ' + r.promptFeedback.blockReason + ')' : '');
} else if (!borrador) {
  motivo = 'Gemini devolvio una respuesta vacia (finishReason=' + (cand.finishReason ?? 'desconocido') + ')';
}

return { json: {
  borrador,
  borrador_valido: motivo === '',
  motivo_error: motivo,
  finish_reason: cand?.finishReason ?? '',
  modelo_rag: String(r.modelVersion ?? 'gemini-3.6-flash'),
  tokens_entrada: r.usageMetadata?.promptTokenCount ?? 0,
  tokens_salida: r.usageMetadata?.candidatesTokenCount ?? 0,
} };

parameters.blocksUi:
={{ (() => {
  const cli = $('Normalizar_Cliente').item.json;
  const cls = $('Parsear_Clasificacion').item.json;
  const borrador = $('Extraer_Borrador_Gemini').item.json.borrador;
  const ticketId = $('Crear_Ticket_Notion').item.json.id;
  const ticketUrl = $('Crear_Ticket_Notion').item.json.url;
  // el borrador va citado linea por linea (max 2500 caracteres: limite de Slack = 3000 por bloque)
  const citado = borrador.slice(0, 2500).split('\n').map((l) => '>' + l).join('\n');
  return { blocks: [
    { type: 'section', text: { type: 'mrkdwn', text:
      '*Nuevo borrador para aprobar*\nCliente: ' + cli.cliente_nombre + ' (' + cli.cliente_email + ')\nPrioridad: ' + cls.prioridad + ' · Sentimiento: ' + cls.sentimiento + ' · Intencion: ' + cls.intencion + (ticketUrl ? '\nTicket: <' + ticketUrl + '|abrir en Notion>' : '') + '\n\n' + citado } },
    { type: 'actions', elements: [
      { type: 'button', text: { type: 'plain_text', text: '✅ Aprobar' }, style: 'primary', value: 'aprobar_' + ticketId, action_id: 'aprobar_ticket' },
      { type: 'button', text: { type: 'plain_text', text: '❌ Rechazar' }, style: 'danger', value: 'rechazar_' + ticketId, action_id: 'rechazar_ticket' }
    ] }
  ] };
})() }}

