// Slack envia application/x-www-form-urlencoded con un campo "payload" (JSON en texto).
const item = $input.item.json;
const bruto = item.body?.payload;
let payload = null;
try {
  payload = typeof bruto === 'string' ? JSON.parse(bruto) : (bruto ?? null);
} catch (e) {
  payload = null;
}

const boton = payload?.actions?.[0];
const valor = typeof boton?.value === 'string' ? boton.value : '';
const sep = valor.indexOf('_');
const accion = sep > 0 ? valor.substring(0, sep) : '';
const ticketId = sep > 0 ? valor.substring(sep + 1) : '';
const idNotion = /^[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}$/i.test(ticketId);
const responseUrl = typeof payload?.response_url === 'string' ? payload.response_url : '';

return { json: {
  valido: payload?.type === 'block_actions' && ['aprobar', 'rechazar'].includes(accion) && idNotion,
  accion,
  ticket_id: ticketId,
  usuario: payload?.user?.name ?? payload?.user?.username ?? payload?.user?.id ?? 'desconocido',
  usuario_id: payload?.user?.id ?? '',
  // solo se acepta la URL de respuesta si es de Slack (evita que un POST falso nos haga llamar a otro host)
  response_url: /^https:\/\/hooks\.slack\.com\//.test(responseUrl) ? responseUrl : '',
  bloque_borrador: payload?.message?.blocks?.[0] ?? null,
} };

