={{ (() => {
  const p = $('Parsear_Click_Slack').item.json;
  const texto = p.accion === 'aprobar'
    ? '✅ *Aprobado* por @' + p.usuario + ' · respuesta enviada al cliente'
    : '❌ *Rechazado* por @' + p.usuario + ' · pasa a revision manual';
  return {
    replace_original: true,
    text: texto,
    blocks: [ p.bloque_borrador, { type: 'context', elements: [ { type: 'mrkdwn', text: texto } ] } ].filter(Boolean)
  };
})() }}

